import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
class IdentityStateService { final FirebaseFirestore db; final FirebaseAuth auth; IdentityStateService({FirebaseFirestore? firestore,FirebaseAuth? firebaseAuth}):db=firestore??FirebaseFirestore.instance,auth=firebaseAuth??FirebaseAuth.instance; Future<void> profile(Map<String,dynamic> patch) async {final uid=auth.currentUser?.uid;if(uid==null)throw StateError('Not signed in');const a={'displayName','username','photoUrl','bio','phone','privacy'};final p=<String,dynamic>{};for(final e in patch.entries){if(a.contains(e.key))p[e.key]=e.value;}if(p.isNotEmpty){p['updatedAt']=FieldValue.serverTimestamp();await db.collection('users').doc(uid).update(p);}} Future<void> device(String id,Map<String,dynamic> meta) async {final uid=auth.currentUser?.uid;if(uid==null)return;await db.collection('users').doc(uid).collection('devices').doc(id).set({...meta,'lastSeenAt':FieldValue.serverTimestamp()},SetOptions(merge:true));}}